/**
 * Public Suffix List lookups (ICANN section only) for registrable-domain (eTLD+1) derivation.
 *
 * Data: ../data/public-suffix-list.json, generated by scripts/build-psl.mjs from a local copy of
 * https://publicsuffix.org/list/public_suffix_list.dat (MPL-2.0, see data/PUBLIC-SUFFIX-LIST-LICENSE.md).
 *
 * The PRIVATE section is deliberately skipped, so hosting platforms such as cloudfront.net or
 * github.io are NOT public suffixes here: `d1.cloudfront.net` has registrable domain
 * `cloudfront.net`. Callers that care about shared hosting must handle it themselves.
 *
 * When no rule matches (e.g. the reserved `.test` TLD) the PSL algorithm's implicit `*` rule
 * applies: the last label is the public suffix.
 *
 * Pure functions, no I/O, never throw. The lookup sets are built lazily on first use.
 */
import pslData from "../data/public-suffix-list.json";
import { isIpAddress, normalizeHostname } from "./hostname.js";

export const PSL_VERSION: {
  fetchedAt: string;
  sourceUrl: string;
  license: string;
  ruleCount: number;
} = {
  fetchedAt: pslData.fetchedAt,
  sourceUrl: "https://publicsuffix.org/list/public_suffix_list.dat",
  license: "MPL-2.0",
  ruleCount: pslData.rules.length,
};

interface PslIndex {
  rules: Set<string>;
  /** Parent part of each `*.parent` rule. */
  wildcards: Set<string>;
  /** Full text of each `!exception` rule. */
  exceptions: Set<string>;
}

let index: PslIndex | undefined;

function getIndex(): PslIndex {
  if (index !== undefined) return index;
  const rules = new Set<string>();
  const wildcards = new Set<string>();
  const exceptions = new Set<string>();
  for (const rule of pslData.rules) {
    if (rule.startsWith("!")) exceptions.add(rule.slice(1));
    else if (rule.startsWith("*.")) wildcards.add(rule.slice(2));
    else rules.add(rule);
  }
  index = { rules, wildcards, exceptions };
  return index;
}

/** Number of labels (from the right) in the public suffix of `labels`. */
function suffixLabelCount(labels: string[]): number {
  const { rules, wildcards, exceptions } = getIndex();
  const n = labels.length;
  const candidates: string[] = new Array<string>(n);
  for (let i = 0; i < n; i++) candidates[i] = labels.slice(i).join(".");

  // An exception rule beats every other rule; the suffix is the rule minus its leftmost label.
  for (let i = 0; i < n; i++) {
    if (exceptions.has(candidates[i] as string)) return n - i - 1;
  }
  // Otherwise the longest matching rule (i.e. the smallest i) prevails.
  for (let i = 0; i < n; i++) {
    if (rules.has(candidates[i] as string)) return n - i;
    if (i + 1 < n && wildcards.has(candidates[i + 1] as string)) return n - i;
  }
  // No rule matched: the implicit "*" rule.
  return 1;
}

function split(hostname: string): string[] | null {
  const host = normalizeHostname(hostname);
  if (host === null || isIpAddress(host)) return null;
  const labels = host.split(".");
  return labels.length >= 2 ? labels : null;
}

/** The public suffix of `hostname` (ICANN rules), or null for IPs, single labels and invalid input. */
export function publicSuffix(hostname: string): string | null {
  const labels = split(hostname);
  if (labels === null) return null;
  return labels.slice(labels.length - suffixLabelCount(labels)).join(".");
}

/**
 * The registrable domain (public suffix plus one label), or null for IPs, single labels, invalid
 * input, or when the whole hostname is itself a public suffix.
 */
export function registrableDomain(hostname: string): string | null {
  const labels = split(hostname);
  if (labels === null) return null;
  const count = suffixLabelCount(labels);
  if (count >= labels.length) return null;
  return labels.slice(labels.length - count - 1).join(".");
}
